//! `lightcraft-cli`: headless Ember.
//!
//! ```text
//! lightcraft-cli run [--demo | --library DIR | --connect [ADDR]] [--import PATH]… CMD [key=value…]…
//! lightcraft-cli mcp [--connect [ADDR]] [--demo] [--compact] [FILES/FOLDERS…]
//! lightcraft-cli render <in> -o <out> [--set control=value]… [--settings FILE.json|FILE.lcpreset] [--preset ID] [--size N] [--quality Q]
//! lightcraft-cli snapshot [--library DIR | --demo] [--script FILE.jsonl] [-o OUT.png] [--size WxH] [--scale S] [FILES…]
//! lightcraft-cli merge hdr|panorama|hdr-panorama [OPTIONS] FILES…
//! lightcraft-cli synth-merge hdr|panorama -o DIR
//! lightcraft-cli denoise-serve [--model ID] [--models DIR] [--listen ADDR] [--token-env VAR] [--run-on auto|gpu|cpu]
//! lightcraft-cli commands [--json]
//! lightcraft-cli controls [--json]
//! lightcraft-cli cull score --predictions FILE --labels FILE [--out FILE] [--split test]
//! lightcraft-cli cull baseline --manifest FILE [--reject-below 0..100] [--out FILE]
//! lightcraft-cli ai personal train --manifest FILE --out NEW_MODEL
//! lightcraft-cli ai personal extract --manifest FILE --out NEW_MANIFEST
//! lightcraft-cli ai personal evaluate --manifest FILE --model FILE [--out NEW_REPORT]
//! lightcraft-cli ai decision manifest --lrcat FILE --raw-root DIR --export-root DIR --out NEW_FILE [--pairs PRIVATE_JSON]
//! lightcraft-cli ai decision extract --manifest PRIVATE_JSON --out NEW_NUMERIC_JSON [--proxy-dir PRIVATE_CACHE]
//! lightcraft-cli ai decision plane --input PRIVATE_TIFF --sha256 EXPECTED_SHA256 --out NEW_PGM
//! lightcraft-cli ai measure --manifest MANIFEST.jsonl --out NEW_OUT.jsonl
//! lightcraft-cli ai denoise baseline --hardware LABEL --out NEW_REPORT
//! lightcraft-cli calibrate [--max N] [--out DIR] FOLDERS/FILES…
//! ```
#![forbid(unsafe_code)]
#![deny(clippy::unwrap_used, clippy::expect_used, clippy::panic, clippy::unimplemented, clippy::todo, clippy::unreachable)]

