fn merge_xmp(xmp: Option<&str>, description: &str) -> String {
    if let Some(x) = xmp
        && let Some(i) = x.rfind("</rdf:RDF>")
        && let (Some(a), Some(b)) = (x.get(..i), x.get(i..))
    {
        return format!("{a}{description}{b}");
    }
    format!("{XMP_OPEN}{description}{XMP_CLOSE}")
}

